// lib/brandAssets.js
//
// The company mark, inlined as a base64 data URI.
//
// WHY INLINE AND NOT /public: every PDF generator in this repo composes its
// document in the BROWSER, and a PDF that references `/matrubhoomi-mark.png`
// renders the letterhead only if the generator fetches and decodes it first.
// @react-pdf/renderer does that for you; pdf-lib does not - its `embedPng`
// takes bytes, never a URL. Inlining removes the fetch, so the artwork is
// identical whether the PDF is built online, offline, or on a machine that
// cannot reach the server at all.
//
// WHAT IS BAKED IN BELOW is now the real thing: the full illustrated lockup —
// the gear-and-leaf emblem over the MATRUBHOOMI wordmark — at 420px, which is
// what the company signs letters with. It replaced the flat placeholder mark
// that used to sit here.
//
// It is a JPEG, not a PNG, and deliberately: the artwork has an opaque backdrop
// so there is no alpha to lose, and the same 420px mark is 81 KB of base64 as a
// JPEG against 392 KB as a PNG — a difference every bundle importing this file
// carries. imageMimeOf() below is what lets the call sites pick embedJpg over
// embedPng, so the swap needed no change at either of them.
//
// DO NOT HAND-EDIT THE LITERAL. It is generated, with every other size of the
// mark, by `node scripts/generate-brand-assets.mjs` from
// public/matrubhoomi-logo-master.webp. Change the master, re-run it, paste.
//
// NEXT_PUBLIC_COMPANY_LOGO_BASE64 still wins when set, for a deployment that
// needs a different mark without a rebuild.

/**
 * Company mark, as a data URI (JPEG today, PNG accepted).
 * Feed through toPngBytes() — which is a misnomer and just decodes base64 —
 * and choose the embed call with imageMimeOf().
 */
export const COMPANY_LOGO_BASE64 =
  process.env.NEXT_PUBLIC_COMPANY_LOGO_BASE64 ||
  "data:image/jpeg;base64,";

/**
 * Decode a PNG (or JPEG) data URI — or a bare base64 payload — to the
 * Uint8Array pdf-lib's embedPng/embedJpg want.
 *
 * Returns null rather than throwing. A letter with no letterhead is a poor
 * letter; a Generate button that dies on a malformed env var is a worse one.
 * Every caller draws the mark only `if (bytes)`.
 */
export function toPngBytes(dataUri) {
  try {
    const raw = String(dataUri || "");
    if (!raw) return null;
    const b64 = raw.includes(",") ? raw.slice(raw.indexOf(",") + 1) : raw;
    if (!b64) return null;
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
    return out;
  } catch {
    return null;
  }
}

/** "image/png" | "image/jpeg" | "" — picks embedPng vs embedJpg at the call site. */
export function imageMimeOf(dataUri) {
  const m = String(dataUri || "").match(/^data:(image\/(?:png|jpe?g));base64,/i);
  if (!m) return "";
  return m[1].toLowerCase() === "image/jpg" ? "image/jpeg" : m[1].toLowerCase();
}
